module.exports="(function fakeSupabase(){\n  const admin='11111111-1111-4111-8111-111111111111',employee='22222222-2222-4222-8222-222222222222';\n  const isAdmin=window.__testRole==='admin';\n  const profile={id:isAdmin?1:2,auth_user_id:isAdmin?admin:employee,employee_name:isAdmin?'Test Administrator':'Sam Employee',auth_email:'fixture@example.invalid',department:'Operations',pin_code:isAdmin?'1101':'2202',employment_type:'Full-Time',active:true,perm_time:true,perm_admin:isAdmin,perm_quotes:isAdmin,perm_collections:isAdmin,perm_commission:true,perm_vehicle_view:false,perm_vehicle_submit:false,perm_safety:true};\n  const start=Math.floor((Date.now()-8*3600000)/60000)*60000;\n  window.__active={auth_user_id:employee,employee_name:'Sam Employee',employee_pin:'2202',department:'Operations',started_at_ms:start,started_at:new Date(start).toISOString(),clock_in_location:'Test shop',clock_in_coords:'',break_minutes:30,lunch_out_at:new Date(start+3*3600000).toISOString(),lunch_in_at:new Date(start+3.5*3600000).toISOString()};\n  window.__clockCalls=[];window.__prefs=JSON.parse(localStorage.getItem('__test_prefs')||'{}');\n  const date=new Date(),day=new Date(date.getFullYear(),date.getMonth(),date.getDate());\n  const stamp=day.getFullYear()+'-'+String(day.getMonth()+1).padStart(2,'0')+'-'+String(day.getDate()).padStart(2,'0');\n  const rows=[{id:1,auth_user_id:profile.auth_user_id,employee_name:profile.employee_name,department:'Operations',work_date:stamp,decimal_hours:7.5,break_minutes:30,clock_in:'08:00',clock_out:'16:00',lunch_review_status:'not_required'}];\n  function from(table){\n    let eq={},rangeStart=0;\n    const query={\n      select(){return query;},order(){return query;},gte(){return query;},lte(){return query;},limit(){return query;},\n      eq(key,value){eq[key]=value;return query;},is(){return query;},or(){return query;},in(){return query;},range(offset){rangeStart=offset;return query;},\n      insert(){return query;},update(){return query;},delete(){return query;},upsert(){return query;},\n      maybeSingle(){return Promise.resolve({data:result(true),error:null});},\n      single(){return query.maybeSingle();},\n      then(resolve,reject){return Promise.resolve({data:result(false),error:null}).then(resolve,reject);}\n    };\n    function result(single){\n      if(rangeStart>0)return [];\n      if(table==='app_users')return single?profile:[profile];\n      if(table==='portal_preferences')return single?{ui_preferences:window.__prefs,dashboard_prefs:{}}:[];\n      if(table==='active_time_sessions')return single?window.__active:(window.__active?[window.__active]:[]);\n      if(table==='time_logs')return single?rows[0]:rows;\n      return single?null:[];\n    }\n    return query;\n  }\n  const channel={on(){return channel;},subscribe(fn){fn?.('SUBSCRIBED');return channel;}};\n  const client={\n    from,channel:()=>channel,removeChannel:async()=>null,\n    auth:{\n      getUser:async()=>({data:{user:{id:profile.auth_user_id,email:profile.auth_email,user_metadata:{}}},error:null}),\n      getSession:async()=>({data:{session:{access_token:'fixture-token',user:{id:profile.auth_user_id}}},error:null}),\n      onAuthStateChange:()=>({data:{subscription:{unsubscribe(){}}}}),signOut:async()=>({error:null})\n    },\n    rpc:async(name,args)=>{\n      if(name==='gp_save_ui_preferences'){Object.assign(window.__prefs,args.p_preferences);localStorage.setItem('__test_prefs',JSON.stringify(window.__prefs));return{data:{ok:true},error:null};}\n      if(name==='gp_finish_active_shift'){window.__clockCalls.push(args);window.__active=null;return{data:{ok:true,already_closed:false,shift_id:'99',decimal_hours:7.5},error:null};}\n      if(name==='gp_employee_directory')return{data:[profile],error:null};\n      return{data:null,error:null};\n    }\n  };\n  window.supabase={createClient:()=>client};\n})();";
